    source: "ANSA",
    url: "https://www.ansa.it/canale_tecnologia/notizie/cybersecurity/2026/11/04/da-binance-agli-smartphone-gli-hacker-mettono-nel-mirino-i-wallet-digitali_d790f8b4-b51f-4808-bce6-83b3e3943ce1.html",
